import type { MetadataRoute } from "next";

import { getSiteSettings } from "@/lib/content";

/**
 * Replaces public/site.webmanifest, which pointed at android-chrome-192x192.png
 * and -512x512.png — neither of which existed. Icons here are the ones
 * generated by app/icon.tsx and app/apple-icon.tsx.
 */
export default async function manifest(): Promise<MetadataRoute.Manifest> {
  const site = await getSiteSettings();

  return {
    name: `${site.name} — ${site.role}`,
    short_name: "Saad Zafar",
    description: site.bioShort,
    start_url: "/",
    display: "standalone",
    background_color: "#04060a",
    theme_color: "#04060a",
    icons: [
      { src: "/icon", sizes: "32x32", type: "image/png" },
      { src: "/apple-icon", sizes: "180x180", type: "image/png" },
    ],
  };
}
